package vn.edu.ltweb.jwtmvc.security; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.web.*; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;
@Configuration public class SecurityConfiguration {@Bean SecurityFilterChain chain(HttpSecurity h,BearerTokenAuthenticationFilter f)throws Exception{return h.csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/auth/**","/login","/profile","/js/**","/error").permitAll().requestMatchers("/users/**").authenticated().anyRequest().permitAll()).exceptionHandling(e->e.authenticationEntryPoint((q,p,x)->{p.setStatus(401);p.setContentType("application/json");p.getWriter().print("{\"status\":401,\"code\":\"UNAUTHORIZED\"}");})).addFilterBefore(f,UsernamePasswordAuthenticationFilter.class).build();}}
